111	export function isDataType(value: unknown): value is DataType {
112	  return (
113	    value instanceof DataType ||
114	    DataType.isNull(value) ||
115	    DataType.isInt(value) ||
116	    DataType.isFloat(value) ||
117	    DataType.isBinary(value) ||
118	    DataType.isLargeBinary(value) ||
119	    DataType.isUtf8(value) ||
120	    DataType.isLargeUtf8(value) ||
121	    DataType.isBool(value) ||
122	    DataType.isDecimal(value) ||
123	    DataType.isDate(value) ||
124	    DataType.isTime(value) ||
125	    DataType.isTimestamp(value) ||
126	    DataType.isInterval(value) ||
127	    DataType.isDuration(value) ||
128	    DataType.isList(value) ||
129	    DataType.isStruct(value) ||
130	    DataType.isUnion(value) ||
131	    DataType.isFixedSizeBinary(value) ||
132	    DataType.isFixedSizeList(value) ||
133	    DataType.isMap(value) ||
134	    DataType.isDictionary(value)
135	  );
136	}
