88	export function sanitizeMetadata(
89	  metadataLike?: unknown,
90	): Map<string, string> | undefined {
91	  if (metadataLike === undefined || metadataLike === null) {
92	    return undefined;
93	  }
94	  if (!(metadataLike instanceof Map)) {
95	    throw Error("Expected metadata, if present, to be a Map<string, string>");
96	  }
97	  for (const item of metadataLike) {
98	    if (!(typeof item[0] === "string" || !(typeof item[1] === "string"))) {
99	      throw Error(
100	        "Expected metadata, if present, to be a Map<string, string> but it had non-string keys or values",
101	      );
102	    }
103	  }
104	  return metadataLike as Map<string, string>;
105	}
