107	export function sanitizeInt(typeLike: object) {
108	  if (
109	    !("bitWidth" in typeLike) ||
110	    typeof typeLike.bitWidth !== "number" ||
111	    !("isSigned" in typeLike) ||
112	    typeof typeLike.isSigned !== "boolean"
113	  ) {
114	    throw Error(
115	      "Expected an Int Type to have a `bitWidth` and `isSigned` property",
116	    );
117	  }
118	  return new Int(typeLike.isSigned, typeLike.bitWidth as IntBitWidth);
119	}
120	
121	export function sanitizeFloat(typeLike: object) {
122	  if (!("precision" in typeLike) || typeof typeLike.precision !== "number") {
123	    throw Error("Expected a Float Type to have a `precision` property");
124	  }
125	  return new Float(typeLike.precision as Precision);
126	}
127	
128	export function sanitizeDecimal(typeLike: object) {
129	  if (
130	    !("scale" in typeLike) ||
131	    typeof typeLike.scale !== "number" ||
132	    !("precision" in typeLike) ||
133	    typeof typeLike.precision !== "number" ||
134	    !("bitWidth" in typeLike) ||
135	    typeof typeLike.bitWidth !== "number"
136	  ) {
137	    throw Error(
138	      "Expected a Decimal Type to have `scale`, `precision`, and `bitWidth` properties",
139	    );
140	  }
141	  return new Decimal(typeLike.scale, typeLike.precision, typeLike.bitWidth);
142	}
143	
144	export function sanitizeDate(typeLike: object) {
145	  if (!("unit" in typeLike) || typeof typeLike.unit !== "number") {
146	    throw Error("Expected a Date type to have a `unit` property");
147	  }
148	  return new Date_(typeLike.unit as DateUnit);
149	}
150	
151	export function sanitizeTime(typeLike: object) {
152	  if (
153	    !("unit" in typeLike) ||
154	    typeof typeLike.unit !== "number" ||
155	    !("bitWidth" in typeLike) ||
156	    typeof typeLike.bitWidth !== "number"
157	  ) {
158	    throw Error(
159	      "Expected a Time type to have `unit` and `bitWidth` properties",
160	    );
161	  }
162	  return new Time(typeLike.unit, typeLike.bitWidth as TimeBitWidth);
163	}
164	
165	export function sanitizeTimestamp(typeLike: object) {
166	  if (!("unit" in typeLike) || typeof typeLike.unit !== "number") {
167	    throw Error("Expected a Timestamp type to have a `unit` property");
168	  }
169	  let timezone = null;
170	  if ("timezone" in typeLike && typeof typeLike.timezone === "string") {
171	    timezone = typeLike.timezone;
172	  }
173	  return new Timestamp(typeLike.unit, timezone);
174	}
175	
176	export function sanitizeTypedTimestamp(
177	  typeLike: object,
178	  // eslint-disable-next-line @typescript-eslint/naming-convention
179	  Datatype:
180	    | typeof TimestampNanosecond
181	    | typeof TimestampMicrosecond
182	    | typeof TimestampMillisecond
183	    | typeof TimestampSecond,
184	) {
185	  let timezone = null;
186	  if ("timezone" in typeLike && typeof typeLike.timezone === "string") {
187	    timezone = typeLike.timezone;
188	  }
