199	export function sanitizeList(typeLike: object) {
200	  if (!("children" in typeLike) || !Array.isArray(typeLike.children)) {
201	    throw Error(
202	      "Expected a List type to have an array-like `children` property",
203	    );
204	  }
205	  if (typeLike.children.length !== 1) {
206	    throw Error("Expected a List type to have exactly one child");
207	  }
208	  return new List(sanitizeField(typeLike.children[0]));
