211	export function sanitizeStruct(typeLike: object) {
212	  if (!("children" in typeLike) || !Array.isArray(typeLike.children)) {
213	    throw Error(
214	      "Expected a Struct type to have an array-like `children` property",
215	    );
216	  }
217	  return new Struct(typeLike.children.map((child) => sanitizeField(child)));
218	}
