30	/**
31	 * Options for a given embedding function
32	 */
33	export interface FunctionOptions {
34	  // biome-ignore lint/suspicious/noExplicitAny: options can be anything
35	  [key: string]: any;
36	}
37	
38	export interface EmbeddingFunctionConstructor<
39	  T extends EmbeddingFunction = EmbeddingFunction,
40	> {
41	  new (modelOptions?: T["TOptions"]): T;
42	}
43	/**
44	 * An embedding function that automatically creates vector representation for a given column.
45	 */
46	export abstract class EmbeddingFunction<
47	  // biome-ignore lint/suspicious/noExplicitAny: we don't know what the implementor will do
48	  T = any,
49	  M extends FunctionOptions = FunctionOptions,
50	> {
51	  /**
52	   * @ignore
53	   *  This is only used for associating the options type with the class for type checking
54	   */
55	  // biome-ignore lint/style/useNamingConvention: we want to keep the name as it is
56	  readonly TOptions!: M;
57	  /**
58	   * Convert the embedding function to a JSON object
59	   * It is used to serialize the embedding function to the schema
60	   * It's important that any object returned by this method contains all the necessary
61	   * information to recreate the embedding function
62	   *
63	   * It should return the same object that was passed to the constructor
64	   * If it does not, the embedding function will not be able to be recreated, or could be recreated incorrectly
65	   *
66	   * @example
67	   * ```ts
68	   * class MyEmbeddingFunction extends EmbeddingFunction {
69	   *   constructor(options: {model: string, timeout: number}) {
70	   *     super();
71	   *     this.model = options.model;
72	   *     this.timeout = options.timeout;
73	   *   }
74	   *   toJSON() {
75	   *     return {
76	   *       model: this.model,
77	   *       timeout: this.timeout,
78	   *     };
79	   * }
80	   * ```
81	   */
82	  abstract toJSON(): Partial<M>;
83	
84	  /**
85	   * sourceField is used in combination with `LanceSchema` to provide a declarative data model
86	   *
87	   * @param optionsOrDatatype - The options for the field or the datatype
88	   *
89	   * @see {@link lancedb.LanceSchema}
90	   */
91	  sourceField(
92	    optionsOrDatatype: Partial<FieldOptions> | DataType,
93	  ): [DataType, Map<string, EmbeddingFunction>] {
94	    let datatype = isDataType(optionsOrDatatype)
95	      ? optionsOrDatatype
96	      : optionsOrDatatype?.datatype;
97	    if (!datatype) {
98	      throw new Error("Datatype is required");
99	    }
100	    datatype = sanitizeType(datatype);
101	    const metadata = new Map<string, EmbeddingFunction>();
102	    metadata.set("source_column_for", this);
103	
104	    return [datatype, metadata];
105	  }
106	
107	  /**
108	   * vectorField is used in combination with `LanceSchema` to provide a declarative data model
109	   *
110	   * @param options - The options for the field
111	   *
112	   * @see {@link lancedb.LanceSchema}
113	   */
114	  vectorField(
115	    optionsOrDatatype?: Partial<FieldOptions> | DataType,
116	  ): [DataType, Map<string, EmbeddingFunction>] {
117	    let dtype: DataType | undefined;
118	    let vectorType: DataType;
119	    let dims: number | undefined = this.ndims();
120	
121	    // `func.vectorField(new Float32())`
122	    if (isDataType(optionsOrDatatype)) {
123	      dtype = optionsOrDatatype;
124	    } else {
125	      // `func.vectorField({
126	      //  datatype: new Float32(),
127	      //  dims: 10
128	      // })`
129	      dims = dims ?? optionsOrDatatype?.dims;
130	      dtype = optionsOrDatatype?.datatype;
131	    }
132	
133	    if (dtype !== undefined) {
134	      // `func.vectorField(new FixedSizeList(dims, new Field("item", new Float32(), true)))`
135	      // or `func.vectorField({datatype: new FixedSizeList(dims, new Field("item", new Float32(), true))})`
136	      if (isFixedSizeList(dtype)) {
137	        vectorType = dtype;
138	        // `func.vectorField(new Float32())`
139	        // or `func.vectorField({datatype: new Float32()})`
140	      } else if (isFloat(dtype)) {
141	        // No `ndims` impl and no `{dims: n}` provided;
142	        if (dims === undefined) {
143	          throw new Error("ndims is required for vector field");
144	        }
145	        vectorType = newVectorType(dims, dtype);
146	      } else {
147	        throw new Error(
148	          "Expected FixedSizeList or Float as datatype for vector field",
149	        );
150	      }
151	    } else {
152	      if (dims === undefined) {
153	        throw new Error("ndims is required for vector field");
154	      }
155	      vectorType = new FixedSizeList(
156	        dims,
157	        new Field("item", new Float32(), true),
158	      );
159	    }
160	    const metadata = new Map<string, EmbeddingFunction>();
161	    metadata.set("vector_column_for", this);
162	
163	    return [vectorType, metadata];
164	  }
165	
166	  /** The number of dimensions of the embeddings */
167	  ndims(): number | undefined {
168	    return undefined;
169	  }
170	
171	  /** The datatype of the embeddings */
172	  abstract embeddingDataType(): Float;
173	
174	  /**
175	   * Creates a vector representation for the given values.
176	   */
177	  abstract computeSourceEmbeddings(
178	    data: T[],
179	  ): Promise<number[][] | Float32Array[] | Float64Array[]>;
180	
181	  /**
182	  Compute the embeddings for a single query
183	 */
184	  async computeQueryEmbeddings(data: T): Promise<Awaited<IntoVector>> {
185	    return this.computeSourceEmbeddings([data]).then(
186	      (embeddings) => embeddings[0],
187	    );
188	  }
189	}
190	
191	export interface FieldOptions<T extends DataType = DataType> {
192	  datatype: T;
193	  dims?: number;
