15	import {
16	  type EmbeddingFunction,
17	  type EmbeddingFunctionConstructor,
18	} from "./embedding_function";
19	import "reflect-metadata";
20	import { OpenAIEmbeddingFunction } from "./openai";
21	
22	interface EmbeddingFunctionCreate<T extends EmbeddingFunction> {
23	  create(options?: T["TOptions"]): T;
24	}
25	
26	/**
27	 * This is a singleton class used to register embedding functions
28	 * and fetch them by name. It also handles serializing and deserializing.
29	 * You can implement your own embedding function by subclassing EmbeddingFunction
30	 * or TextEmbeddingFunction and registering it with the registry
31	 */
32	export class EmbeddingFunctionRegistry {
33	  #functions = new Map<string, EmbeddingFunctionConstructor>();
34	
35	  /**
36	   * Register an embedding function
37	   * @param name The name of the function
38	   * @param func The function to register
39	   * @throws Error if the function is already registered
40	   */
41	  register<
42	    T extends EmbeddingFunctionConstructor = EmbeddingFunctionConstructor,
43	  >(
44	    this: EmbeddingFunctionRegistry,
45	    alias?: string,
46	    // biome-ignore lint/suspicious/noExplicitAny: <explanation>
47	  ): (ctor: T) => any {
48	    const self = this;
49	    return function (ctor: T) {
50	      if (!alias) {
51	        alias = ctor.name;
52	      }
53	      if (self.#functions.has(alias)) {
54	        throw new Error(
55	          `Embedding function with alias "${alias}" already exists`,
56	        );
57	      }
58	      self.#functions.set(alias, ctor);
59	      Reflect.defineMetadata("lancedb::embedding::name", alias, ctor);
60	      return ctor;
61	    };
62	  }
63	
64	  /**
65	   * Fetch an embedding function by name
66	   * @param name The name of the function
67	   */
68	  get<T extends EmbeddingFunction<unknown>, Name extends string = "">(
69	    name: Name extends "openai" ? "openai" : string,
70	    //This makes it so that you can use string constants as "types", or use an explicitly supplied type
71	    // ex:
72	    // `registry.get("openai") -> EmbeddingFunctionCreate<OpenAIEmbeddingFunction>`
73	    // `registry.get<MyCustomEmbeddingFunction>("my_func") -> EmbeddingFunctionCreate<MyCustomEmbeddingFunction> | undefined`
74	    //
75	    // the reason this is important is that we always know our built in functions are defined so the user isnt forced to do a non null/undefined
76	    // ```ts
77	    // const openai: OpenAIEmbeddingFunction = registry.get("openai").create()
78	    // ```
79	  ): Name extends "openai"
80	    ? EmbeddingFunctionCreate<OpenAIEmbeddingFunction>
81	    : EmbeddingFunctionCreate<T> | undefined {
82	    type Output = Name extends "openai"
83	      ? EmbeddingFunctionCreate<OpenAIEmbeddingFunction>
84	      : EmbeddingFunctionCreate<T> | undefined;
85	
86	    const factory = this.#functions.get(name);
87	    if (!factory) {
88	      return undefined as Output;
89	    }
90	
91	    return {
92	      create: function (options?: T["TOptions"]) {
93	        return new factory(options);
94	      },
95	    } as Output;
96	  }
97	
98	  /**
99	   * reset the registry to the initial state
100	   */
101	  reset(this: EmbeddingFunctionRegistry) {
102	    this.#functions.clear();
103	  }
104	
105	  /**
106	   * @ignore
107	   */
108	  parseFunctions(
109	    this: EmbeddingFunctionRegistry,
110	    metadata: Map<string, string>,
111	  ): Map<string, EmbeddingFunctionConfig> {
112	    if (!metadata.has("embedding_functions")) {
113	      return new Map();
114	    } else {
115	      type FunctionConfig = {
116	        name: string;
117	        sourceColumn: string;
118	        vectorColumn: string;
119	        model: EmbeddingFunction["TOptions"];
120	      };
121	      const functions = <FunctionConfig[]>(
122	        JSON.parse(metadata.get("embedding_functions")!)
123	      );
124	      return new Map(
125	        functions.map((f) => {
126	          const fn = this.get(f.name);
127	          if (!fn) {
128	            throw new Error(`Function "${f.name}" not found in registry`);
129	          }
130	          return [
131	            f.name,
132	            {
133	              sourceColumn: f.sourceColumn,
134	              vectorColumn: f.vectorColumn,
135	              function: this.get(f.name)!.create(f.model),
136	            },
137	          ];
138	        }),
139	      );
140	    }
141	  }
142	  // biome-ignore lint/suspicious/noExplicitAny: <explanation>
143	  functionToMetadata(conf: EmbeddingFunctionConfig): Record<string, any> {
144	    // biome-ignore lint/suspicious/noExplicitAny: <explanation>
145	    const metadata: Record<string, any> = {};
146	    const name = Reflect.getMetadata(
147	      "lancedb::embedding::name",
148	      conf.function.constructor,
149	    );
150	    metadata["sourceColumn"] = conf.sourceColumn;
151	    metadata["vectorColumn"] = conf.vectorColumn ?? "vector";
152	    metadata["name"] = name ?? conf.function.constructor.name;
153	    metadata["model"] = conf.function.toJSON();
154	    return metadata;
155	  }
156	
157	  getTableMetadata(functions: EmbeddingFunctionConfig[]): Map<string, string> {
158	    const metadata = new Map<string, string>();
159	    const jsonData = functions.map((conf) => this.functionToMetadata(conf));
160	    metadata.set("embedding_functions", JSON.stringify(jsonData));
161	
162	    return metadata;
163	  }
164	}
165	
166	const _REGISTRY = new EmbeddingFunctionRegistry();
167	
168	export function register(name?: string) {
169	  return _REGISTRY.register(name);
170	}
171	
172	/**
173	 * Utility function to get the global instance of the registry
174	 * @returns `EmbeddingFunctionRegistry` The global instance of the registry
175	 * @example
176	 * ```ts
177	 * const registry = getRegistry();
178	 * const openai = registry.get("openai").create();
179	 */
180	export function getRegistry(): EmbeddingFunctionRegistry {
181	  return _REGISTRY;
182	}
183	
184	export interface EmbeddingFunctionConfig {
185	  sourceColumn: string;
186	  vectorColumn?: string;
187	  function: EmbeddingFunction;
188	}
