27	/**
28	 * Create a schema with embedding functions.
29	 *
30	 * @param fields
31	 * @returns Schema
32	 * @example
33	 * ```ts
34	 * class MyEmbeddingFunction extends EmbeddingFunction {
35	 * // ...
36	 * }
37	 * const func = new MyEmbeddingFunction();
38	 * const schema = LanceSchema({
39	 *   id: new Int32(),
40	 *   text: func.sourceField(new Utf8()),
41	 *   vector: func.vectorField(),
42	 *   // optional: specify the datatype and/or dimensions
43	 *   vector2: func.vectorField({ datatype: new Float32(), dims: 3}),
44	 * });
45	 *
46	 * const table = await db.createTable("my_table", data, { schema });
47	 * ```
48	 */
49	export function LanceSchema(
50	  fields: Record<string, [object, Map<string, EmbeddingFunction>] | object>,
51	): Schema {
52	  const arrowFields: Field[] = [];
53	
54	  const embeddingFunctions = new Map<
55	    EmbeddingFunction,
56	    Partial<EmbeddingFunctionConfig>
57	  >();
58	  Object.entries(fields).forEach(([key, value]) => {
59	    if (isDataType(value)) {
60	      arrowFields.push(new Field(key, sanitizeType(value), true));
61	    } else {
62	      const [dtype, metadata] = value as [
63	        object,
64	        Map<string, EmbeddingFunction>,
65	      ];
66	      arrowFields.push(new Field(key, sanitizeType(dtype), true));
67	      parseEmbeddingFunctions(embeddingFunctions, key, metadata);
68	    }
69	  });
70	  const registry = getRegistry();
71	  const metadata = registry.getTableMetadata(
72	    Array.from(embeddingFunctions.values()) as EmbeddingFunctionConfig[],
73	  );
74	  const schema = new Schema(arrowFields, metadata);
75	  return schema;
76	}
77	
78	function parseEmbeddingFunctions(
79	  embeddingFunctions: Map<EmbeddingFunction, Partial<EmbeddingFunctionConfig>>,
80	  key: string,
81	  metadata: Map<string, EmbeddingFunction>,
82	): void {
83	  if (metadata.has("source_column_for")) {
84	    const embedFunction = metadata.get("source_column_for")!;
85	    const current = embeddingFunctions.get(embedFunction);
86	    if (current !== undefined) {
87	      embeddingFunctions.set(embedFunction, {
88	        ...current,
89	        sourceColumn: key,
90	      });
91	    } else {
92	      embeddingFunctions.set(embedFunction, {
93	        sourceColumn: key,
94	        function: embedFunction,
95	      });
96	    }
97	  } else if (metadata.has("vector_column_for")) {
98	    const embedFunction = metadata.get("vector_column_for")!;
99	
100	    const current = embeddingFunctions.get(embedFunction);
101	    if (current !== undefined) {
102	      embeddingFunctions.set(embedFunction, {
103	        ...current,
104	        vectorColumn: key,
105	      });
106	    } else {
107	      embeddingFunctions.set(embedFunction, {
108	        vectorColumn: key,
109	        function: embedFunction,
110	      });
111	    }
112	  }
113	}
